<script setup>
import { ref, computed } from 'vue';
const props=defineProps(['data','results','loading','testing','connected','publicModels','publicBusy']);defineEmits(['refresh','refresh-public','test']);
const selected=ref('');const row=computed(()=>props.data?.項目.find(item=>item.id===selected.value));const result=computed(()=>props.results[selected.value]);
const config=item=>item.設定済み===null?'確認不可':item.設定済み?'設定済':'未設定';
</script>
<template>
<section class="panel" aria-label="キー設定状況"><div class="panel-heading"><h2>キー設定状況</h2><button :disabled="!connected || loading || Boolean(testing)" @click="$emit('refresh')">設定状況を更新</button></div><p class="panel-note">キーの値は表示しません。設定済みでも接続は未確認です。テストはモデル一覧の取得のみで、起動時にキーなしで取得した公開 OpenRouter 情報を補完に利用します。取得前・失敗時も、警告付きで個別テストできます。文章生成・MCP・CLI の試行は行いません。</p>
<div class="public-status"><p role="status">{{publicModels?.説明 || '公開モデルはまだ取得していません。'}} <span v-if="publicModels?.状態==='取得済'">{{publicModels.件数}} 件</span></p><button :disabled="!connected || publicBusy || publicModels?.状態==='取得中'" @click="$emit('refresh-public')">{{publicBusy || publicModels?.状態==='取得中'?'公開モデル取得中…':'公開モデルを再取得'}}</button></div><main class="key-layout"><aside aria-label="キーの一覧"><p v-if="loading">設定状況を確認中…</p><p v-else-if="!data">接続すると設定状況を表示します。</p><template v-else><p>設定ファイル: {{data.設定状態}}</p><p v-if="data.説明" role="status">{{data.説明}}</p><div v-for="item in data.項目" :key="item.id" class="key-row" :class="{selected:selected===item.id}"><button class="key-select" :aria-pressed="selected===item.id" @click="selected=item.id"><span>{{item.名前}}</span><small>{{item.キー名}}</small><span class="config-state">{{config(item)}}{{item.キー不要 ? ' · 一覧取得はキー不要' : ''}}</span></button><div class="key-test"><span class="public-indicator" :data-public-state="publicModels?.状態 || '未取得'">{{publicModels?.状態==='取得済'?'公開モデル取得済':publicModels?.状態==='取得中'?'公開モデル取得中':publicModels?.状態==='失敗'?'公開モデル取得失敗':'公開モデル未取得'}}</span><button :disabled="!connected || Boolean(testing) || loading || !item.テスト可能" :title="item.キー不要 ? '取得済み公開モデルを表示します。キーの有効性は確認しません。' : item.理由 || 'このキーでモデル一覧を取得します'" @click="selected=item.id;$emit('test',item.id)">{{testing===item.id?'確認中…':'テスト'}}</button><span class="badge" :data-state="results[item.id]?.状態 || '未実施'">{{results[item.id]?.状態 || '未実施'}}</span></div></div></template></aside>
<article aria-live="polite"><template v-if="row"><span class="eyebrow">キー設定状況 / {{row.名前}}</span><h2>{{row.名前}}</h2><span class="status" :data-state="result?.状態 || '未実施'">{{result?.状態 || '未実施'}}</span><dl><dt>キー名</dt><dd>{{row.キー名}}</dd><dt>設定状況</dt><dd>{{config(row)}}</dd><dt>確認内容</dt><dd>{{row.説明}}</dd><dt>テスト</dt><dd>{{result?.説明 || row.理由 || '未実施。左側のテストボタンでモデル一覧を取得します。'}}</dd><dt>確認日時</dt><dd>{{result?.確認日時?new Date(result.確認日時).toLocaleString():'—'}}</dd></dl><h3>モデル一覧</h3><p v-if="result?.一覧範囲">{{result.一覧範囲}}</p><p v-if="result?.補完">{{result.補完}}</p><ul v-if="result?.モデル?.length" class="models"><li v-for="model in result.モデル" :key="model"><strong>{{model}}</strong><template v-for="detail in (result.モデル詳細 || []).filter(item=>item.model_id===model)" :key="detail.model_id"><br><span class="model-meta">作成日: {{detail.作成日 || '不明'}} · トークン数: {{detail.トークン数 || '不明'}} · モダリティ: {{detail.モダリティ || '不明'}}</span></template></li></ul><p v-else>{{result?.状態==='OK'?'取得結果にモデルがありません。':'まだモデルを取得していません。'}}</p><p v-for="warning in result?.警告 || []" :key="warning" class="warning">{{warning}}</p><p>OK はモデル一覧 API の応答確認です。生成の可否・権限・料金を保証しません。</p></template><div v-else class="welcome"><span class="eyebrow">KEY CONFIGURATION</span><h2>キーとモデル</h2><p>左側のキーを選ぶと、設定状況とテスト結果・モデル一覧を表示します。</p><p>起動時はキー不要の公開一覧だけを取得します。個別キーのテストはボタンを押したときだけです。「全テスト」の対象にも含めません。</p></div></article></main></section>
</template>
